import pathlib, sys, re
problems = []
patterns = [re.compile(r'sk-[A-Za-z0-9]{16,}'), re.compile(r'Bearer\s+[A-Za-z0-9._-]{20,}')]
for p in sorted(pathlib.Path('.').rglob('*')):
    if not p.is_file() or '.git' in p.parts:
        continue
    if p.suffix not in ('.go', '.md', '.json', '.yml', '.yaml', '.txt'):
        continue
    try:
        text = p.read_text(encoding='utf-8')
    except (UnicodeDecodeError, OSError):
        continue
    for pattern in patterns:
        if pattern.search(text):
            problems.append(p.as_posix() + ': looks like a credential')
print('no credential literal in the tree: OK' if not problems else repr(problems))
sys.exit(1 if problems else 0)

