import pathlib, sys
mk = pathlib.Path('Makefile').read_text(encoding='utf-8')
main = pathlib.Path('scripts/doccheck/main.go').read_text(encoding='utf-8')
problems = []
for token in ['fmt-check', 'vet', 'test', 'coverage', 'docs', 'doc-examples', 'build']:
    if token not in mk:
        problems.append('Makefile lost gate ' + token)
for token in ['100 < current.total*90', 'has no coverage data']:
    if token not in main:
        problems.append('coverage gate weakened: ' + token)
print('gate integrity: OK' if not problems else 'problems: ' + repr(problems))
sys.exit(1 if problems else 0)

